import importlib.util, json, math, time
from urllib.error import HTTPError
p='/Users/leungvw/.codex/skills/ccdi-federation-ai-copilot/scripts/ccdi_client.py'
spec=importlib.util.spec_from_file_location('ccdi_client',p)
ccdi=importlib.util.module_from_spec(spec); spec.loader.exec_module(ccdi)
base='https://federation.ccdi.cancer.gov/api/v1/'
brain_dx=[
 'Atypical Teratoid/Rhabdoid Tumors',
 'Choroid Plexus Tumors',
 'CNS Germ Cell Tumors',
 'CNS Sarcomas',
 'Craniopharyngiomas',
 'Ependymoma',
 'Glioneuronal and Neuronal Tumors',
 'High-Grade Glioma',
 'Low-Grade Gliomas',
 'Medulloblastoma',
 'Other CNS Embryonal Tumors',
 'Other Gliomas',
 'Other Brain Tumors',
]
per_page=100
all_records=[]
fetch_log=[]
node_errors=[]
for dx in brain_dx:
    page=1
    seen_pages=set()
    dx_records=0
    while True:
        params={'diagnosis':dx,'page':page,'per_page':per_page}
        r=ccdi.read_only_get(base,'/sample-diagnosis',params,timeout_seconds=60,max_retries=1)
        if not r['ok']:
            fetch_log.append({'diagnosis':dx,'page':page,'ok':False,'errors':r['errors']})
            break
        payload=r['payload']
        if not isinstance(payload, list):
            fetch_log.append({'diagnosis':dx,'page':page,'unexpected_payload_type':type(payload).__name__})
            break
        page_current=0
        page_all_by_source={}
        for node in payload:
            source=node.get('source','UNKNOWN')
            if node.get('errors'):
                for err in node.get('errors') or []:
                    # Deduplicate repeated node invalid-route errors later
                    node_errors.append({'source':source,'diagnosis':dx,'page':page,'error':err})
                continue
            data=node.get('data') or []
            page_current += len(data)
            summary=node.get('summary') or {}
            page_all_by_source[source]=(summary.get('counts') or {}).get('all')
            for rec in data:
                rec['_source']=source
                rec['_query_diagnosis']=dx
                all_records.append(rec)
                dx_records += 1
        fetch_log.append({'diagnosis':dx,'page':page,'current':page_current,'all_by_source':page_all_by_source})
        if page_current < per_page:
            break
        page += 1
        if page > 200:
            fetch_log.append({'diagnosis':dx,'stop':'page_cap'})
            break
# Deduplicate samples first, then subjects. A sample can be returned via multiple dx queries if diagnosis arrays/strings overlap.
def ns_key(obj):
    if not obj: return None
    ns=obj.get('namespace') or {}
    return (ns.get('organization'), ns.get('name'), obj.get('name'))
def key_str(k):
    return '|'.join('' if x is None else str(x) for x in k)
unique_samples={}
for rec in all_records:
    k=ns_key(rec.get('id')) or (rec.get('_source'), json.dumps(rec.get('id'), sort_keys=True))
    unique_samples.setdefault(k, rec)
subjects={}
for rec in unique_samples.values():
    sk=ns_key(rec.get('subject')) or ('NO_SUBJECT', ns_key(rec.get('id')), rec.get('_source'))
    # If duplicated subject has multiple sample records, prefer one with known age, then smaller age if conflicting.
    meta=rec.get('metadata') or {}
    age=meta.get('age_at_diagnosis')
    cur=subjects.get(sk)
    if cur is None:
        subjects[sk]=rec
    else:
        cur_age=(cur.get('metadata') or {}).get('age_at_diagnosis')
        if cur_age in (None,'') and age not in (None,''):
            subjects[sk]=rec
        elif age not in (None,'') and cur_age not in (None,''):
            try:
                if float(age) < float(cur_age):
                    subjects[sk]=rec
            except Exception:
                pass
# Age conversion: API docs say sample age fields are approximate age in days (verify below). Convert to years.
def parse_age_days(v):
    if v in (None,''):
        return None
    try:
        x=float(v)
    except Exception:
        return None
    if math.isnan(x): return None
    return x
bins=[('0-<1',0,1),('1-4',1,5),('5-9',5,10),('10-14',10,15),('15-19',15,20),('20+',20,math.inf)]
dist={b[0]:0 for b in bins}
known=[]
missing=[]
by_dx={}
conflicts=[]
for sk, rec in subjects.items():
    meta=rec.get('metadata') or {}
    age_days=parse_age_days(meta.get('age_at_diagnosis'))
    diags=meta.get('diagnosis')
    if isinstance(diags, list):
        diag_list=diags
    elif diags is None:
        diag_list=[]
    else:
        diag_list=[diags]
    for d in diag_list:
        if d in brain_dx:
            by_dx[d]=by_dx.get(d,0)+1
    if age_days is None:
        missing.append((sk,rec))
    else:
        years=age_days/365.25
        known.append((sk,rec,age_days,years))
        for label, lo, hi in bins:
            if lo <= years < hi:
                dist[label]+=1
                break
# Check conflict rate among samples for same subject ages.
age_by_subject={}
for rec in unique_samples.values():
    sk=ns_key(rec.get('subject')) or ('NO_SUBJECT', ns_key(rec.get('id')), rec.get('_source'))
    age=parse_age_days((rec.get('metadata') or {}).get('age_at_diagnosis'))
    age_by_subject.setdefault(sk,set()).add(age)
for sk, ages in age_by_subject.items():
    clean={a for a in ages if a is not None}
    if len(clean)>1:
        conflicts.append((sk, sorted(clean)[:10], len(clean)))
# Source counts
source_sample_counts={}
source_subject_counts={}
for rec in unique_samples.values():
    source_sample_counts[rec.get('_source','UNKNOWN')]=source_sample_counts.get(rec.get('_source','UNKNOWN'),0)+1
for sk, rec in subjects.items():
    source_subject_counts[rec.get('_source','UNKNOWN')]=source_subject_counts.get(rec.get('_source','UNKNOWN'),0)+1
err_summary={}
for e in node_errors:
    key=(e['source'], e['error'].get('kind'), e['error'].get('message'))
    err_summary[key]=err_summary.get(key,0)+1
out={
 'queried_diagnoses': brain_dx,
 'total_raw_sample_records_from_queries': len(all_records),
 'unique_samples': len(unique_samples),
 'deduplicated_subjects': len(subjects),
 'known_age_subjects': len(known),
 'missing_age_subjects': len(missing),
 'age_distribution_year_bins': dist,
 'source_sample_counts': source_sample_counts,
 'source_subject_counts': source_subject_counts,
 'by_diagnosis_subject_counts_nonexclusive': dict(sorted(by_dx.items())),
 'age_years_summary': {
   'min': round(min([x[3] for x in known]),2) if known else None,
   'median': round(sorted([x[3] for x in known])[len(known)//2],2) if known else None,
   'max': round(max([x[3] for x in known]),2) if known else None,
 },
 'subjects_with_conflicting_known_ages_across_samples': len(conflicts),
 'first_conflicts': [{'subject': key_str(c[0]), 'ages_days': c[1], 'distinct_known_age_count': c[2]} for c in conflicts[:10]],
 'node_error_summary': [{'source':k[0], 'kind':k[1], 'message':k[2], 'count':v} for k,v in err_summary.items()],
 'fetch_log_first_20': fetch_log[:20],
 'fetch_log_len': len(fetch_log),
}
print(json.dumps(out, indent=2))
PY"

