/bin/bash -lc "python3 - <<'PY'
import importlib.util, json, math
p='/Users/leungvw/.codex/skills/ccdi-federation-ai-copilot/scripts/ccdi_client.py'
spec=importlib.util.spec_from_file_location('ccdi_client',p)
ccdi=importlib.util.module_from_spec(spec); spec.loader.exec_module(ccdi)
base='https://federation.ccdi.cancer.gov/api/v1/'
per_page=100
query='brain tumor'
all_records=[]
fetch_log=[]
node_errors=[]
page=1
while True:
    r=ccdi.read_only_get(base,'/sample-diagnosis',{'search':query,'page':page,'per_page':per_page},timeout_seconds=60,max_retries=1)
    if not r['ok']:
        fetch_log.append({'page':page,'ok':False,'errors':r['errors']})
        break
    payload=r['payload']
    if not isinstance(payload,list):
        fetch_log.append({'page':page,'unexpected_payload_type':type(payload).__name__})
        break
    page_current=0
    all_by_source={}
    for node in payload:
        source=node.get('source','UNKNOWN')
        if node.get('errors'):
            for err in node.get('errors') or []:
                node_errors.append({'source':source,'page':page,'error':err})
            continue
        data=node.get('data') or []
        page_current += len(data)
        all_by_source[source]=(node.get('summary') or {}).get('counts',{}).get('all')
        for rec in data:
            rec['_source']=source
            all_records.append(rec)
    fetch_log.append({'page':page,'current':page_current,'all_by_source':all_by_source})
    if page_current < per_page:
        break
    page += 1
    if page > 50:
        fetch_log.append({'stop':'page_cap'})
        break

def ident_key(obj):
    if not obj: return None
    ns=obj.get('namespace') or {}
    return (ns.get('organization'), ns.get('name'), obj.get('name'))

def get_val(field):
