  for page in range(1,max_pages+1):
    r=ccdi.read_only_get(base,'/sample-diagnosis',{'search':query,'page':page,'per_page':per_page},timeout_seconds=60,max_retries=1)
    payload=r.get('payload')
    if not r['ok'] or not isinstance(payload,list):
      logs.append({'per_page':per_page,'page':page,'ok':r['ok'],'status':r.get('status'),'errors':r.get('errors')}); continue
    current_by_source={}; all_by_source={}
    for node in payload:
      src=node.get('source','UNKNOWN')
      if node.get('errors'):
        for err in node.get('errors') or []: errors.append({'source':src,'page':page,'per_page':per_page,'error':err})
        continue
      data=node.get('data') or []
      current_by_source[src]=len(data)
      all_by_source[src]=(node.get('summary') or {}).get('counts',{}).get('all')
      for rec in data:
        rec['_source']=src
        rec['_fetch_per_page']=per_page
        all_records.append(rec)
    logs.append({'per_page':per_page,'page':page,'current_by_source':current_by_source,'all_by_source':all_by_source})

