  if not obj: return None
  ns=obj.get('namespace') or {}
  return (ns.get('organization'), ns.get('name'), obj.get('name'))
def key_str(k): return '/'.join('' if x is None else str(x) for x in k)
def get_val(field):
  if field is None: return None
  if isinstance(field, dict) and 'value' in field: return field.get('value')
  return field
def parse_float(v):
  v=get_val(v)
  if v in (None,''): return None
  try: x=float(v)
  except (TypeError,ValueError): return None
  return None if math.isnan(x) else x
unique_samples={}
for rec in all_records:
  k=ident_key(rec.get('id')) or (rec.get('_source'), json.dumps(rec.get('id'), sort_keys=True))
  unique_samples.setdefault(k,rec)
subjects={}; subject_all_ages={}; sample_counts={}; source_samples={}
for rec in unique_samples.values():
  source_samples[rec.get('_source','UNKNOWN')]=source_samples.get(rec.get('_source','UNKNOWN'),0)+1
  sk=ident_key(rec.get('subject')) or ('NO_SUBJECT', ident_key(rec.get('id')), rec.get('_source'))
  sample_counts[sk]=sample_counts.get(sk,0)+1
  age=parse_float((rec.get('metadata') or {}).get('age_at_diagnosis'))
  subject_all_ages.setdefault(sk,set()).add(age)
  cur=subjects.get(sk)
  if cur is None: subjects[sk]=rec
  else:
    cur_age=parse_float((cur.get('metadata') or {}).get('age_at_diagnosis'))
    if cur_age is None and age is not None: subjects[sk]=rec
    elif cur_age is not None and age is not None and age < cur_age: subjects[sk]=rec
bins=[('0-<1',0,1),('1-4',1,5),('5-9',5,10),('10-14',10,15),('15-19',15,20),('20+',20,math.inf)]
dist={b[0]:0 for b in bins}; known=[]; missing=[]; source_subjects={}; diag_counts={}
for sk,rec in subjects.items():
  src=rec.get('_source','UNKNOWN'); source_subjects[src]=source_subjects.get(src,0)+1
  meta=rec.get('metadata') or {}; age=parse_float(meta.get('age_at_diagnosis'))
  diag=get_val(meta.get('diagnosis'))
  comment=meta.get('diagnosis',{}).get('comment') if isinstance(meta.get('diagnosis'),dict) else None
  label=comment or diag
  if label: diag_counts[label]=diag_counts.get(label,0)+1
  if age is None: missing.append(sk)
  else:
    yrs=age/365.25; known.append((sk,age,yrs,src,label))
    for name,lo,hi in bins:
      if lo <= yrs < hi: dist[name]+=1; break
conflicts=[]
for sk,ages in subject_all_ages.items():
  clean=sorted(a for a in ages if a is not None)
  if len(set(clean))>1: conflicts.append({'subject':key_str(sk),'ages_years':[round(a/365.25,2) for a in clean]})
err_by_source={}
for e in errors:
  k=(e['source'],e['error'].get('kind'))
  err_by_source[k]=err_by_source.get(k,0)+1
ages=[x[2] for x in known]
print(json.dumps({
 'raw_records_collected_before_union':len(all_records),
