 'source_sample_counts':dict(sorted(source_samples.items())),'source_subject_counts':dict(sorted(source_subjects.items())),
 'top_diagnoses_or_comments':sorted(diag_counts.items(), key=lambda x:(-x[1],x[0]))[:20],
 'subjects_with_multiple_samples':sum(1 for n in sample_counts.values() if n>1),
 'subjects_with_conflicting_known_ages':len(conflicts),'conflict_examples':conflicts[:10],
