      current_by_source[src]=len(data)
      all_by_source[src]=(node.get('summary') or {}).get('counts',{}).get('all')
      for rec in data:
        rec['_source']=src
        rec['_fetch_per_page']=per_page
        all_records.append(rec)
    logs.append({'per_page':per_page,'page':page,'current_by_source':current_by_source,'all_by_source':all_by_source})

def ident_key(obj):
  if not obj: return None
  ns=obj.get('namespace') or {}
  return (ns.get('organization'), ns.get('name'), obj.get('name'))
